struct Parcel {
    let track: String
    let daysLeft: Int?
}
func deliveryText(for parcel: Parcel) -> String {
    "Осталось \(parcel.daysLeft) дн."
}
print(deliveryText(for: Parcel(track: "RB12", daysLeft: 3)))
print(deliveryText(for: Parcel(track: "RB13", daysLeft: nil)))

key:
func deliveryText(for parcel: Parcel) -> String {
    guard let days = parcel.daysLeft else { return "Срок уточняется" }
    return "Осталось \(days) дн."
}

Интерполяция Optional компилируется (только с предупреждением) и печатает «Осталось Optional(3) дн.» и «Осталось nil дн.». Значение разворачивают до вставки в текст: guard let отсекает nil, дальше days — обычный Int. Теперь вывод «Осталось 3 дн.» и «Срок уточняется». ?? 0 здесь не подходит: «Осталось 0 дн.» соврал бы о сроке.

